#include "cgobind.h"
static event_cb g_cb = NULL;
static void* g_ctx = NULL;

void register_event_source(event_cb cb, void* ctx) {
  g_cb = cb;
  g_ctx = ctx;
}

void emit_event(int event) {
  if (g_cb) g_cb(event, g_ctx);
